<template><div class="page"><h1>离线故障数据集生成</h1><p>按项目路线覆盖动力与电源典型系统，生成带故障真值和注入时间的 CSV，并完成诊断闭环。</p><el-card><el-form inline><el-form-item label="子系统"><el-select v-model="form.subsystem" @change="changeSubsystem"><el-option v-for="(_,s) in options" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="故障模式"><el-select v-model="form.fault_mode"><el-option v-for="m in options[form.subsystem]||[]" :key="m" :label="m" :value="m"/></el-select></el-form-item><el-form-item label="注入时间"><el-input-number v-model="form.injection_time" :min="1" :max="119"/></el-form-item><el-form-item label="严重度"><el-slider v-model="form.severity" :min=".1" :max="1" :step=".1"/></el-form-item><el-button type="primary" :loading="loading" @click="generate">生成故障 CSV 并分析</el-button></el-form></el-card><el-card v-if="result" class="result"><el-alert title="故障链路分析完成，数据集已保存" type="success"/><el-steps :active="7" finish-status="success" simple><el-step v-for="s in stages" :key="s" :title="s"/></el-steps><el-descriptions border :column="3"><el-descriptions-item label="数据集 ID">{{result.dataset_id}}</el-descriptions-item><el-descriptions-item label="诊断">{{result.result.diagnosis.fault}}</el-descriptions-item><el-descriptions-item label="隔离部位">{{result.result.isolation.target}}</el-descriptions-item><el-descriptions-item label="健康指数">{{result.result.health.component_hi}}</el-descriptions-item><el-descriptions-item label="RUL">{{result.result.rul.value}} 样本间隔</el-descriptions-item><el-descriptions-item label="消息发布">{{result.result.notification.published?'已发布':'未发布'}}</el-descriptions-item></el-descriptions><el-table :data="result.preview"><el-table-column prop="time" label="时间"/><el-table-column prop="pressure" label="压力"/><el-table-column prop="temperature" label="温度"/><el-table-column prop="bus_voltage" label="母线电压"/><el-table-column prop="battery_capacity" label="电池容量"/><el-table-column prop="HI_norm" label="健康指数"/></el-table></el-card></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';const options=ref({}),loading=ref(false),result=ref(null),stages=['注入','告警','诊断','隔离','健康评估','RUL','发布'],form=ref({subsystem:'动力',fault_mode:'泄漏',severity:.6,injection_time:40});function changeSubsystem(){form.value.fault_mode=options.value[form.value.subsystem]?.[0]||''}onMounted(async()=>options.value=(await(await fetch('/api/v1/simulation-demo/sample/')).json()).subsystems);async function generate(){loading.value=true;try{let r=await fetch('/api/v1/simulation-demo/workflows/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form.value,mode:'offline',name:`${form.value.subsystem}-${form.value.fault_mode}`})});let j=await r.json();if(!r.ok)throw Error(j.error);r=await fetch(`/api/v1/simulation-demo/workflows/${j.task.id}/generate/`,{method:'POST'});j=await r.json();if(!r.ok)throw Error(j.error);result.value=j;ElMessage.success('故障数据集已生成')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}</script>
<style scoped>.page{max-width:1300px}.page>p{color:#67788e}.el-select{width:160px}.el-slider{width:150px}.result{margin-top:18px}.el-alert,.el-steps,.el-descriptions,.el-table{margin-bottom:18px}</style>
